"""Final report uses executed final-tree evidence, never historical candidate counts."""
from pathlib import Path
import json,hashlib,subprocess
R=Path(__file__).resolve().parents[1];D=R/'reports'
def read(name):return json.loads((D/name).read_text(encoding='utf8'))
def sha(p):return hashlib.sha256(p.read_bytes()).hexdigest()

def main():
 backend=read('institution_v2q2_backend_tests.json');front=read('institution_v2q2_frontend_tests.json');pres=read('institution_v2q2_preservation.json')
 assert backend['source_stable'] and backend['group_count']==38
 frozen=read('institution_v2q2_final_source.json')['source_sha256'];assert all(sha(R/n)==h for n,h in frozen.items())
 cleanup=read('institution_v2q2_fixture_cleanup.json');assert cleanup['database_removed'] and cleanup['owned_lab_path_removed']
 services=read('institution_v2q2_service_switch.json');assert services['restored']
 compare=read('institution_v2q2_candidate_comparison.json');references=read('institution_v2q2_references_final.json');assert references['complete']
 single=read('institution_v2q2_single_page.json');recommend=read('institution_v2q2_recommendation_matrix.json');security=read('institution_v2q2_security.json');repairs=read('institution_v2q2_repairs.json')
 browser=read('institution_v2q2_browser_qa.json');approval=read('institution_v2q2_approval_record.json');drift=read('institution_v2q2_metadata_drift.json')
 fail=backend['counts']['failed']+front['counts']['fail'];result='FAIL' if fail or backend['exit'] or not all(x['exit']==0 for x in front['checks']) else 'PARTIAL'
 qa={'PART_2Q2_RESULT':result,'PRIVATE_B_VALIDATOR':'CANDIDATE_ONLY','PROTECTED_PATCH_APPROVED':'NO','PROTECTED_SOURCE_CHANGED_WITHOUT_APPROVAL':'NO',
     'FALSE_PREMISE_REJECTION':'PARTIAL','FOREIGN_DOCUMENT_DENIAL':'PASS','MULTI_TURN_CONTEXT':'PARTIAL','LIBRARY_SWITCH_ISOLATION':'PASS',
     'PRIVATE_FOR_YOU':'PARTIAL','REAL_BROWSER_QA':'PARTIAL','HUMAN_RELEVANCE':'UNAVAILABLE','LIVE_METADATA_DRIFT':'UNATTRIBUTED',
     'BACKEND_TESTS':' / '.join(str(backend['counts'][k]) for k in ['passed','failed','skipped']),
     'FRONTEND_TESTS':' / '.join(str(front['counts'][k]) for k in ['pass','fail','skipped']),
     'NEW_REGRESSIONS':fail,'GLOBAL_HNSW_REBUILT':'NO','GLOBAL_KG_REBUILT':'NO','PRODUCTION_AUTH_CHANGED':'NO','PRODUCTION_TELEMETRY_ENABLED':'NO','DEPLOYED':'NO','COMMITTED':'NO'}
 (D/'institution_v2q2_final_qa.json').write_text(json.dumps(qa,indent=2))
 (D/'institution_v2q2_regression.json').write_text(json.dumps({'baseline_backend':[3097,0,20],'actual_final_backend':backend['counts'],'baseline_frontend':[1028,0,0],'actual_frontend':front['counts'],'new_automated_regressions':fail,'new_test_cases':5,'focused_final':[21,0,0],'affected_final':[439,0,0],'counts_do_not_include_repeated_focused_runs':True,'quality_not_inferred_from_green_software_tests':True,'current_model_defects':['Private B original validator false negative','Original validator also accepts some adversarial/conflicting evidence','Proposed candidate expands false positives','Digital-copy browser question receives physical stock counts','Global fixture similar-book discovery clarifies instead of completing'],'intermediate_regression':'Reordering examples disturbed Global first/third comparison; final source preserves exact prior serialization for3+book contexts; final4/4pairs resolve correctly. All attempts retained.'},indent=2))
 orig=compare['matrix']['original'];cand=compare['matrix']['candidate'];b=backend['counts']
 sections=[
 ('A. FINAL PASS / PARTIAL / FAIL', f'{result}. The protected candidate remains unapproved and fails the expanded safety review. Software regression results and remaining model limitations are reported separately.'),
 ('B. CURRENT BASELINE', f'Initial backend: 3097/0/20; frontend: 1028/0/0. Final backend: {qa["BACKEND_TESTS"]}; frontend: {qa["FRONTEND_TESTS"]}. Existing dirty work and Git HEAD are preserved. The final run freezes 554 baseline source files plus the two new test/fixture files.'),
 ('C. PROTECTED VALIDATOR REVIEW', 'Verified patch SHA-256: 53a4bbd40eb950622b28a7e5b2b2c0daf9390d1f9dc5d16c5de3ed5031a31c92. The existing Qwen judge exposes supported/confidence only. It receives the question, structured intent and up to three passage texts; authorization is enforced outside the model. Entity, field, negation and conflict matching remain semantic. The informational prompt and qa.py are unchanged. See institution_v2q2_validator_review.md for exact source context and contract impact.'),
 ('D. PRIVATE B ROOT CAUSE', 'Fresh equivalent synthetic PDFs reproduced A answers in 3/3 runs and B answers in 0/3. The B fact survives extraction, chunking, real MiniLM/FAISS retrieval, reranking, context selection and validator input. The original validator returns NOT_SUPPORTED; refusal and source removal follow that decision. The judge exposes no internal explanation. Selected synthetic passages, verdict details, answers, sources and timings are retained in private_B_analysis.json and private_stages.jsonl.'),
 ('E. CANDIDATE BEFORE/AFTER RESULTS', f'The isolated candidate answers A and B in 3/3 runs each using the same resident engine and prepared assets. Each variant retains 6/6 outsider denials. The separate validator matrix covers 25 categories plus four bounded repeats: 58 runs, 56 genuine Qwen calls and two empty-evidence refusals before inference. Original verdicts match {orig["matched_expectation"]}/29 strict expectations; candidate verdicts match {cand["matched_expectation"]}/29. The direct matrix generates no final answers; synthetic PDF answers are recorded separately. No failed run was discarded.'),
 ('F. SECURITY NEGATIVE TESTS', f'The original accepts {orig["strict_negative_acceptance"][0]}/{orig["strict_negative_acceptance"][1]} strict-negative cases; the candidate accepts {cand["strict_negative_acceptance"][0]}/{cand["strict_negative_acceptance"][1]}. Clear new candidate failures include wrong entity, wrong field and absent value. False-premise and injection controls also fail; conflicts and injection expose original weaknesses. Yes/no and contradiction oracles can differ from a corrective-answer policy, which is documented. Entity/field failures do not depend on that ambiguity. Raw provenance challenges are separate from access control: all 20 authenticated security checks pass, denied calls produce no private answer, and outsider/revoked browser resource access is denied. Exact per-case evidence is in validator_matrix.json/.md.'),
 ('G. PATCH APPROVAL STATUS', 'NOT APPROVED and NOT APPLIED. Do not apply this candidate based on positive coverage alone. The exact historical diff is retained in institution_v2q2_protected_validator_proposal.patch together with adverse review evidence. Its CRLF check fails against the LF source; a separately hashed LF review copy passes check-only application. Both results are retained in patch_checks.json. Neither artifact is applied. Any source and contract revision requires separate exact approval. Original manifests, frozen tests and protected qa.py/llm.py remain intact; no arbitrary-version exception was added.'),
 ('H. CONVERSATIONAL REFERENCES', 'Only QwenGateway._reference_examples changed. Nonexistent second/third positions now demonstrate clarification, and a single current book has a canonical-ID availability example. For three or more books, example serialization exactly matches the previous revision. No parsed decision override, scope rewrite, schema, lock or resolver change occurred. The final 36 genuine Qwen questions cover Global, A, B and I: all 20 identity assertions match, all four ambiguous that-one requests clarify, and no foreign book IDs return. Eight additional single-page cases pass. Broader semantic coverage remains partial.'),
 ('I. BOOK AVAILABILITY', 'All eight second-item/selected-book availability cases and four single-page stock cases resolve correctly. The final B browser answer confirms two available copies out of two. Its digital-copy follow-up incorrectly repeats physical stock counts despite a visible online resource. This remains an unresolved semantic defect; stock counts are not evidence of digital availability. Four broader API digital-copy cases clarify.'),
 ('J. PRIVATE FOR YOU', 'All ten ownership cases pass across A, B, single-book, five-book, empty, cold-start and unmapped/nonmatching Global-candidate fixtures. GLOBAL_INTERSECTION_AND_LOCAL_DISCOVERY is unchanged; fresh local-only acquisitions remain eligible. Scoped results belong to the selected library, and the empty library returns no tenant recommendations. A/B browser rails retain local metadata; all 84 observed B book links belong to B. Relevance remains unreviewed. The controlled Global provider supplies IDs without complete recommendation metadata, producing Unknown Title cards; this is a diagnostic fixture limitation.'),
 ('K. BROWSER QA', 'PARTIAL. One owned IAB session remained available without tab loss. Previous port 18017 was offline after intentional fixture cleanup; the cause of earlier tab disappearance is not proven. This run covers login/logout/relogin, Global For You, A/B For You, book navigation, genuine Global/A/B Qwen cases, private-resource and revocation denial, no-match search, library switching and keyboard Skip-link focus. A successful held A response is canceled on B navigation, with an exact request-ID match and no A conversation content. This is controlled transport timing, not proof of overlapping Qwen generation. A requested 390px viewport produced browser-imposed 487px inner/469px client width; page scroll width was 469px, so exact 390px coverage remains unverified. Missing diagnostic facets 404, temporary library-update 503 and a reload-overlap 502 are retained. Console warnings/errors: zero. See browser_qa.json for exact coverage.'),
 ('L. HUMAN RELEVANCE REVIEW STATUS', 'All 50 original and 20 prior private ranking rows are preserved exactly. The readable 70-row worksheet includes query, library, rank, title, author, metadata, constraints, scale 0/1/2/3/UNKNOWN, and blank reviewer/rationale fields. Human judgments: zero. No relevance labels or Precision@K, MRR or nDCG were fabricated.'),
 ('M. LIVE METADATA DRIFT', 'The historical audit increment of five, membership increment of one and security digest change remain unattributed. The audit sequence is three failed private joins, an access-code change and a successful private join; membership joined_at matches the final event. Counts remain 1935/130/49 during this phase. Current fixture IDs do not appear in those live collections, and prior Part 2Q.1 reports do not reference that scope. Initiator/approval evidence is unavailable. No personal identities were exported, and no live data was rolled back or overwritten.'),
 ('N. QWEN PERFORMANCE', 'Original/candidate validator pairs use the same resident Qwen with identical schema, evidence and authored intent, alternating order and bounded repeats. The latency export retains model loads, exposed input/generated tokens, retrieval/evidence/validation/generation/tool timings and total request time. Sequential A/B cache warming limits causal latency conclusions; direct encode counts exclude chat framing. No first-token/prefill measurements were invented. Precision, provider, inference lock and token caps are unchanged. Only one Qwen model process ran at a time; later serial reloads verified unprotected prompt revisions after candidate comparison finished.'),
 ('O. BACKEND REGRESSION', f'Final accepted product inventory: 38 groups, {b["passed"]} passed / {b["failed"]} failed / {b["skipped"]} skipped, with source unchanged throughout. Coverage includes Assistant, RAG/private authorization, conversation isolation, Search, recommendations, KG, tenant authority, availability, Events, announcements, notifications, Staff, frozen guards, Mongo configuration, operator access and native protocols. The preliminary run is retained but excluded from final closure because source changed during it. Focused 21/0/0 and affected Assistant 439/0/0 repeats are separate, without double counting or suppression.'),
 ('P. FRONTEND REGRESSION', f'Executed npm test: {qa["FRONTEND_TESTS"]}. Frontend application source is unchanged. Counts come from current execution logs.'),
 ('Q. BUILD / LINT', 'Production build and lint exit zero. Initial lint had 18 warnings, including two from disposable Vite configuration. Final lint after cleanup is separately recorded and compared with the previous 16-warning baseline. No lint exclusions or warning suppression were added.'),
 ('R. GLOBAL PRESERVATION', f'Current-phase preservation: {pres["result"]}. Source, global catalogue/HNSW/KG, ranking, recommendations, model configuration, tenant artifacts/holdings, private/personal data, authority/protocols, announcements/notifications and .env checks are recorded. Large artifacts use size/mtime checks. Historical drift remains a separate qualification. Only three explicit initial Search builds ran for newly created fixtures; no existing tenant/global rebuild, auth cutover, telemetry activation, deployment or commit occurred. Owned DB/assets/sessions/temp frontend are removed and regular local RAG is restored.'),
 ('S. EXACT SOURCE CHANGES', 'Application: assistant/qwen.py only, one method. Added tests/institution_v2q_ai/test_v2q2_reference_examples.py and fixtures/v2q1d_three_book_examples.json, covering five new cases. All other Qwen executable AST is unchanged. The complete source/test/script/report inventory and hashes are in institution_v2q2_changed_files.json. Unprotected diff SHA-256: '+sha(D/'institution_v2q2_unprotected_changes.patch')+'. Protected proposal SHA-256: '+approval['patch_sha256']+'; unapplied.'),
 ('T. REMAINING BLOCKERS', 'The candidate fails grounding safety review and actual Private B abstention remains unresolved. Some original judge adversarial cases also fail. Digital-copy phrasing and Global related-book discovery remain incomplete. Diagnostic provider/facets and viewport limitations prevent full production browser claims. Independent human judgments and historical metadata ownership evidence remain unavailable. Green software tests do not establish general model accuracy.'),
 ('U. NEXT RECOMMENDED ACTION', 'Reject application of the current protected candidate. Review a more precise grounding revision against the full negative matrix before requesting exact source/guard approval. Obtain independent relevance labels and complete remaining production-equivalent browser checks in a separately authorized follow-up. Stop after Part 2Q.2; Part 2R has not started.')]
 text='# LuminaR Part 2Q.2\n\n'+'\n\n'.join('## '+title+'\n\n'+body for title,body in sections)+'\n\n## FINAL QA\n\n'+'\n\n'.join(k+': '+str(v) for k,v in qa.items())+'\n'
 (D/'institution_v2q2_completion.md').write_text(text,encoding='utf8')
 names={'assistant/qwen.py','tests/institution_v2q_ai/test_v2q2_reference_examples.py','tests/institution_v2q_ai/fixtures/v2q1d_three_book_examples.json'}
 for folder in ['scripts','reports']:
  names.update(p.relative_to(R).as_posix() for p in (R/folder).glob('*') if p.is_file() and ('institution_v2q2_' in p.name or 'institution_v2q_2q2_' in p.name))
 manifest='reports/institution_v2q2_changed_files.json';names.add(manifest)
 files=[{'path':n,'sha256':None if n==manifest else sha(R/n),'category':'application' if n=='assistant/qwen.py' else 'test_or_fixture' if n.startswith('tests/') else 'task_script' if n.startswith('scripts/') else 'evidence'} for n in sorted(names)]
 (R/manifest).write_text(json.dumps({'files':files,'application_changes':['assistant/qwen.py'],'unprotected_patch_sha256':sha(D/'institution_v2q2_unprotected_changes.patch'),'protected_proposal_sha256':approval['patch_sha256'],'protected_applied':False,'source_baseline':'institution_v2q2_checkpoint.json','scope':'Source,test,taskscript/reportartifacts; generatedbytecode/buildcaches and removeddisposabledata excluded. Manifest ownhash omitted toavoidself-reference.','before_snapshot':{'path':'.scratch/institution-v2q/validator-review/before/assistant/qwen.py','sha256':sha(R/'.scratch/institution-v2q/validator-review/before/assistant/qwen.py')}},indent=2))
 print(json.dumps({'result':result,'backend':b,'frontend':front['counts'],'files':len(files),'protected_applied':False}))

if __name__=='__main__':main()
